def quest_id(chapter, n):
    return f'13{chapter:02X}00000000{n:04X}'

def write_full_book(root, json):
    for chapter, (slug, title, prerequisite, goals) in enumerate(CHAPTERS, start=0x10):
        quests = []
        for n, (name, pairs, text) in enumerate(goals, start=1):
            tasks = [dict(task, id=f'24{chapter:02X}{n:04X}0000{i:04X}')
                     for i, task in enumerate(items(*pairs))]
            quests.append({'id': quest_id(chapter,n), 'title': name,
                'description': [text, 'Общий зачёт команды FTB Teams. Предметы остаются у вас; награда — следующий раздел книги.'],
                'x': float((n-1)%4*4), 'y': float((n-1)//4*4),
                'dependencies': [quest_id(chapter,5 if chapter in (0x15,0x16) and n==7 else n-1) if n>1 else prerequisite], 'tasks':tasks})
            gate = {'storage':5,'gt_lv':5,'gt_mv':5,'hbm_industry':5,'gt_hv_ev':6,'gt_iv_luv':7,'gt_zpm_uv':9}.get(slug)
            if n==1 and gate: quests[-1]['dependencies'].append(f'140000000000{gate:04X}')
            if slug=='gt_iv_luv' and n==5: quests[-1]['dependencies'].append('1400000000000008')
        (root/'chapters'/f'{slug}.snbt').write_text(json.dumps({
            'id':f'300000000000{chapter:04X}', 'filename':slug, 'title':title,
            'order_index': chapter+10, 'quests':quests},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
